CREATE OR REPLACE FUNCTION public.is_owner_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND store_id=public.current_store_id() AND role IN ('admin','owner')) $$;
CREATE OR REPLACE FUNCTION public.can_manage_payment_types(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_manage_staff(_user_id) $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.log_activity()'::regprocedure) INTO d; d:=replace(d,'INSERT INTO activity_log(user_id, action, details) VALUES (u, a, left(d, 200))','INSERT INTO activity_log(user_id, action, details,store_id) VALUES (u, a, left(d, 200),NEW.store_id)'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_role text:=NEW.raw_app_meta_data->>'initial_role'; sid uuid; BEGIN IF v_role NOT IN ('admin','owner','manager','supervisor','cashier','stock_controller','accountant') OR v_role IS NULL THEN RAISE EXCEPTION 'Public staff registration is closed'; END IF; sid:=nullif(NEW.raw_app_meta_data->>'store_id','')::uuid; IF sid IS NULL THEN SELECT id INTO sid FROM public.stores WHERE is_vendor_store; END IF; IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=sid) THEN RAISE EXCEPTION 'Store not found'; END IF; INSERT INTO public.profiles(id,full_name,username,store_id) VALUES(NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'full_name',''),split_part(NEW.email,'@',1)),lower(coalesce(nullif(NEW.raw_user_meta_data->>'username',''),split_part(NEW.email,'@',1))),sid); INSERT INTO public.store_memberships(user_id,store_id) VALUES(NEW.id,sid); INSERT INTO public.user_roles(user_id,role,store_id) VALUES(NEW.id,v_role::public.app_role,sid); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.check_staff_pin(p_username text,p_pin text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE r record; BEGIN SELECT sp.*,p.active INTO r FROM public.staff_pins sp JOIN public.profiles p ON p.id=sp.user_id JOIN public.store_memberships m ON m.user_id=p.id AND m.store_id=sp.store_id WHERE p.username=lower(trim(p_username)) AND p.store_id=sp.store_id FOR UPDATE OF sp; IF NOT FOUND OR NOT r.active THEN RETURN NULL; END IF; IF r.locked_until>now() THEN RETURN NULL; END IF; IF r.pin_hash=crypt(p_pin,r.pin_hash) THEN UPDATE public.staff_pins SET failed_attempts=0,locked_until=NULL WHERE user_id=r.user_id; RETURN r.user_id; END IF; UPDATE public.staff_pins SET failed_attempts=CASE WHEN failed_attempts+1>=5 THEN 0 ELSE failed_attempts+1 END,locked_until=CASE WHEN failed_attempts+1>=5 THEN now()+interval '5 minutes' ELSE locked_until END WHERE user_id=r.user_id; INSERT INTO public.activity_log(user_id,action,store_id) VALUES(r.user_id,'pin_failed',r.store_id); RETURN NULL; END $$;
COMMENT ON COLUMN public.profiles.username IS 'Globally unique staff sign-in identity. Customer stores namespace created staff usernames; vendor legacy identities remain unchanged.';